(async () => {
  if (!game.user.isGM) { ui.notifications.warn("BR2 Relink Notes: GM only."); return; }

  const MOD = "blooming-rot-2";
  const jPacks = game.packs.filter(p => p.metadata.packageName === MOD && p.documentName === "JournalEntry");
  if (!jPacks.length) { ui.notifications.error("BR2 Relink Notes: no Blooming Rot 2 journal compendia found."); return; }

  // Build: compendium entryId -> {name, pages:{pageId:pageName}, pack}
  const srcById = new Map();
  for (const pack of jPacks) {
    const index = await pack.getIndex({ fields: ["pages"] });
    for (const e of index) {
      const pages = {};
      for (const pg of (e.pages ?? [])) pages[pg._id] = pg.name;
      srcById.set(e._id, { name: e.name, pages, pack: pack.collection });
    }
  }

  const sourceOf = d => d?._stats?.compendiumSource ?? d?.flags?.core?.sourceId ?? "";
  const worldByName = new Map();
  const worldBySrcId = new Map();
  for (const j of game.journal) {
    worldByName.set(j.name, j);
    const m = /JournalEntry\.([A-Za-z0-9]+)/.exec(sourceOf(j));
    if (m) worldBySrcId.set(m[1], j);
  }

  const scenes = game.scenes.contents;
  let ok = 0, fixed = 0, dead = 0, noNotes = 0;
  const missingJournals = new Set();
  const perScene = [];

  for (const scene of scenes) {
    const notes = scene.notes.contents;
    if (!notes.length) { noNotes++; continue; }
    const updates = [];
    let sOk = 0, sFix = 0, sDead = 0;

    for (const note of notes) {
      if (note.entryId && game.journal.get(note.entryId)) { sOk++; ok++; continue; }
      const src = srcById.get(note.entryId);
      if (!src) { sDead++; dead++; continue; }
      const target = worldBySrcId.get(note.entryId) ?? worldByName.get(src.name);
      if (!target) { sDead++; dead++; missingJournals.add(src.name); continue; }

      const upd = { _id: note.id, entryId: target.id };
      if (note.pageId) {
        const wantName = src.pages[note.pageId];
        let page = target.pages.get(note.pageId);
        if (!page && wantName) page = target.pages.find(p => p.name === wantName);
        if (!page) page = target.pages.find(p => {
          const m = /JournalEntryPage\.([A-Za-z0-9]+)/.exec(sourceOf(p));
          return m && m[1] === note.pageId;
        });
        upd.pageId = page ? page.id : null;
      }
      updates.push(upd); sFix++; fixed++;
    }

    if (updates.length) await scene.updateEmbeddedDocuments("Note", updates);
    perScene.push({ name: scene.name, ok: sOk, fixed: sFix, dead: sDead });
  }

  const rows = perScene.map(s =>
    `<tr><td>${s.name}</td><td style="text-align:center">${s.ok}</td>` +
    `<td style="text-align:center"><strong>${s.fixed}</strong></td>` +
    `<td style="text-align:center">${s.dead ? "<strong>" + s.dead + "</strong>" : "0"}</td></tr>`).join("");

  let advice = "";
  if (missingJournals.size) {
    advice = `<p><strong>Import these journals into your world, then run this again:</strong></p><ul>` +
      [...missingJournals].sort().map(n => `<li>${n}</li>`).join("") + `</ul>`;
  } else if (!fixed && ok) {
    advice = `<p>Every pin already resolves to a world journal. If you still cannot click a pin: ` +
      `switch to the <strong>Journal Notes</strong> layer in the left toolbar (the bookmark icon) &mdash; ` +
      `notes are only selectable, movable and deletable while that layer is active &mdash; and make sure ` +
      `<strong>Toggle Notes Display</strong> is on.</p>`;
  }

  ChatMessage.create({
    content: `<h3>Blooming Rot 2 &mdash; Relink Scene Notes</h3>
      <p>Scenes checked: <strong>${scenes.length}</strong> (${noNotes} with no pins). ` +
      `Pins already linked: <strong>${ok}</strong>. Repaired: <strong>${fixed}</strong>. Unresolved: <strong>${dead}</strong>.</p>
      <table style="width:100%"><thead><tr><th style="text-align:left">Scene</th><th>OK</th><th>Fixed</th><th>Dead</th></tr></thead>
      <tbody>${rows}</tbody></table>${advice}`,
    whisper: [game.user.id]
  });
  ui.notifications.info(`BR2 Relink Notes: ${fixed} repaired, ${ok} already fine, ${dead} unresolved.`);
})();
